import lens

TARGET = "price_for"
DEPTH = 2

resp = lens.callers(TARGET, transitive=True, depth=DEPTH, prod_only=True)
nodes = resp.get("nodes", [])

candidates = {}
for n in nodes:
    name = n.get("name")
    file = n.get("file", "")
    if name == TARGET or not file.startswith("src/obs/"):
        continue
    candidates[name] = file

def sig_block(text, name):
    lines = text.splitlines()
    for i, line in enumerate(lines):
        if f"fn {name}(" in line or f"fn {name}<" in line:
            block = []
            for l in lines[i:i + 6]:
                block.append(l)
                if "{" in l:
                    break
            return "\n".join(block)
    return ""

skel_cache = {}
with_path = []
for name, file in candidates.items():
    if file not in skel_cache:
        sk = lens.skeleton(file)
        skel_cache[file] = sk.get("skeleton", "") if isinstance(sk, dict) else str(sk)
    if "&Path" in sig_block(skel_cache[file], name):
        with_path.append(name)

with_path.sort()
print(f"target=price_for transitive_callers={len(candidates)} with_path_param={len(with_path)}")
print(",".join(with_path))
